SELECT 
FROM marketing_flash_session


        AND name LIKE CONCAT('%', #{name,jdbcType=VARCHAR}, '%')


        AND status = #{status,jdbcType=TINYINT}


        AND start_time >= #{startTimeFrom,jdbcType=TIMESTAMP}


        AND start_time <= #{startTimeTo,jdbcType=TIMESTAMP}


ORDER BY start_time DESC, id DESC

SELECT 
FROM marketing_flash_session
WHERE status = #{status,jdbcType=TINYINT}
  AND end_time >= #{nowDateTime,jdbcType=TIMESTAMP}
ORDER BY start_time ASC, id ASC

SELECT 
FROM marketing_flash_session
WHERE status = #{status,jdbcType=TINYINT}
  AND start_time >= #{from,jdbcType=TIMESTAMP}
  AND start_time <= #{to,jdbcType=TIMESTAMP}
ORDER BY start_time ASC, id ASC

SELECT 
FROM marketing_flash_session
WHERE status = #{status,jdbcType=TINYINT}
  AND start_time < #{endTime,jdbcType=TIMESTAMP}
  AND end_time > #{startTime,jdbcType=TIMESTAMP}

      AND id != #{excludeId,jdbcType=BIGINT}

ORDER BY start_time ASC

